//www.tei-c.org/ns/1.0\" xml:id=\"S01520.5.11.3.3\">\n                     <ns0:label rend=\"size(larger)                   pad(rlb)             ornamented() color() other()\">ג<ns0:am rend=\"overdot\">׳</ns0:am>\n                     </ns0:label> חטאת לזו ועולה לזו עשה\n              \n<ns0:lb n=\"27\" />\n               כולם למעלן מחצה כשר ומחצה פסול כולם למטן<ns0:space unit=\"chars\" extent=\"8\" /> מחצה כשר\n              ומחצה פסול\n              \n<ns0:lb n=\"28\" />\n               חצין למעלן וחצין למטן שתיהם פסולות שאני אומ<ns0:am rend=\"overmark\">׳</ns0:am>  חטאת קרבה למעלן ועולה למטן<ns0:pc type=\"unitEnd\" rend=\"gershayyim\" />\n                     <ns0:lb n=\"29\" />\n                  </ns0:ab>\n                  "},"3:4":{"id":"S01520.5.11.3.4","text":"חטאת ועולה וסתומה ומפורשת עשה כולם למעלה מחצה כשר ומחצה פסול כולן למטן מחצה כשר מחצה פסול חציה למעלן וחציה למטן אין כשר אלא סתומה והיא מתחלקת ביניהם","offsetText":"\n                      חטאת ועולה וסתומה ומפורשת עשה כולם למעלה מחצה כשר\n              ומחצה פסול\n              \n \n                     כולן למטן מחצה כשר מחצה פסול חציה למעלן וחציה למטן אין\n              כשר אלא סתומה\n                      \n                      \n               והיא מתחלקת ביניהם\n                  ","words":[{"start":23,"end":27,"text":"חטאת","key":"חטאת","flags":[]},{"start":28,"end":33,"text":"ועולה","key":"ועולה","flags":[]},{"start":34,"end":40,"text":"וסתומה","key":"וסתומה","flags":[]},{"start":41,"end":48,"text":"ומפורשת","key":"ומפורשת","flags":[]},{"start":49,"end":52,"text":"עשה","key":"עשה","flags":[]},{"start":53,"end":57,"text":"כולם","key":"כולם","flags":[]},{"start":58,"end":63,"text":"למעלה","key":"למעלה","flags":[]},{"start":64,"end":68,"text":"מחצה","key":"מחצה","flags":[]},{"start":69,"end":72,"text":"כשר","key":"כשר","flags":[]},{"start":87,"end":92,"text":"ומחצה","key":"ומחצה","flags":[]},{"start":93,"end":97,"text":"פסול","key":"פסול","flags":[]},{"start":136,"end":140,"text":"כולן","key":"כו